changeSet.sql:
DO $$
DECLARE
    stale_count INTEGER;
    stale_list  TEXT;
BEGIN
    SELECT COUNT(*) INTO stale_count
    FROM providers
    WHERE LOWER(provider_type::text) = 'ollama';
    IF stale_count > 0 THEN
        SELECT COALESCE(STRING_AGG('#' || p.id || ' ' || p.name, ', '), '')
        INTO stale_list
        FROM providers p
        WHERE LOWER(p.provider_type::text) = 'ollama';
        RAISE EXCEPTION
            'Logos no longer supports providers of type ''ollama'' and % provider row(s) still use it: %. Re-type them as ''logosnode'' (worker-backed) or delete them, then restart the webservice.',
            stale_count, stale_list;
    END IF;
END;
$$;
